// Build the direct-fetchable image URL from the Drive file id.
// This format (not the normal drive.google.com/file/d/.../view share
// link) is what a plain HTTP GET -- which is what Instagram's own
// fetcher does -- can actually read as raw image bytes.
const fileId = $('Webhook: /instagram-post').item.json.body.media_items[0].media_ref;
const caption = $('Webhook: /instagram-post').item.json.body.caption;
const requestId = $('Webhook: /instagram-post').item.json.body.request_id;

return {
  json: {
    image_url: `https://drive.google.com/uc?export=view&id=${fileId}`,
    caption,
    request_id: requestId,
  }
};
